```python
class Company:
    def __init__(self, name, employees):
        self.name = name
        self.employees = employees

    def get_employees(self):
        return self.employees

    def add_employee(self, employee):
        self.employees.append(employee)

    def remove_employee(self, employee):
        self.employees.remove(employee)


class Employee:
    def __init__(self, name, password):
        self.name = name
        self.password = password

    def get_name(self):
        return self.name

    def get_password(self):
        return self.password


def main():
    company = Company("ABC Inc.", [])

    # Add employees to the company
    company.add_employee(Employee("John Doe", "password123"))
    company.add_employee(Employee("Jane Smith", "iloveyou"))
    company.add_employee(Employee("Bob Johnson", "hello"))

    # Simulate an information theft
    print("Company Employees:")
    for employee in company.get_employees():
        print(f"Name: {employee.get_name()}, Password: {employee.get_password()}")

    # Identify potential security weaknesses
    weak_passwords = [employee for employee in company.get_employees() if employee.get_password() in ["password123", "iloveyou", "hello"]]
    print("\nPotential Security Weaknesses:")
    for employee in weak_passwords:
        print(f"Name: {employee.get_name()}, Password: {employee.get_password()}")


if __name__ == "__main__":
    main()
```

